WITH kept_keys AS (SELECT country FROM sessions INTERSECT ALL SELECT country FROM sessions WHERE device IN ('tablet', 'desktop')), kept_rows AS (SELECT s.* FROM sessions s JOIN kept_keys k ON s.country = k.country) SELECT s.id, s.customer_id, s.device, s.browser, s.started_at, (SELECT SUM(x.monthly_fee) FROM subscriptions x WHERE x.customer_id = s.customer_id) AS sum_subscription_monthly_fee FROM kept_rows s ORDER BY started_at DESC NULLS LAST, id DESC;
